using EqlTracker.Core;

internal static class BardCompatibilityAcceptance
{
    internal static void Register(Action<string,Action> test)
    {
        static void Check(bool value){if(!value)throw new Exception("Bard/compatibility acceptance failed");}
        var now=DateTime.Now;
        EffectInput Effect(string id,string family,double amount)=>new(){Identity=new(id,id,0),Family=family,Amount=amount,Quality=EvidenceQuality.UserConfirmed,Source="Synthetic observed values"};
        (BardSetup Setup,CoverageObservation Other,EffectRule Rule,EvaluationContext Context) Fixture(double own=30,double external=40)
        {
            var a=new BardSong{Identity=new("a","My haste",0),Gem=8,Mana=0,CooldownMs=0,NonTargetedArea=true,Available=true,RequiredLevel=1,Effects=[Effect("a","HastePercent",own)]};
            var b=new CoverageObservation{Id="landing",Song=new("b","Other haste",0),Caster="OtherBard",Recipient="Hero",At=now.AddSeconds(-1),Until=now.AddSeconds(10),SuccessfulApplication=true,Attribution=EvidenceQuality.Observed,Instrument=1,Singing=1,Focus=1,EffectiveCasterLevel=50,AaContext="Reviewed fixture",Effects=[Effect("b","HastePercent",external)]};
            var setup=new BardSetup{ConfirmedAuraRank=1,AuraEvidence="Fixture",Instrument=1,Singing=1,Focus=1,EffectiveCasterLevel=50,AaContext="Reviewed fixture",Songs=[a],Available=[new(){Identity=new("c","Missing mana",0),Available=true,RequiredLevel=1,Mana=0,CooldownMs=0,NonTargetedArea=true,Effects=[Effect("c","ManaRegen",5)]}]};
            var rule=new EffectRule{Id="strongest",Source="Reviewed fixture",Version="1",Quality=EvidenceQuality.UserConfirmed,Kind=EffectRuleKind.Strongest,Family="HastePercent",SpellIds=["a","b"]};
            return(setup,b,rule,new(){Character="Hero",Recipient="Hero",Classes=["BRD"],CasterLevel=50});
        }
        foreach(var potency in new[]{(Own:30d,Other:40d,Expected:1),(Own:40d,Other:40d,Expected:1),(Own:50d,Other:40d,Expected:0)})
            test("Bard equal/unequal potency "+potency.Own+" vs "+potency.Other,()=>{var f=Fixture(potency.Own,potency.Other);var view=BardCoverage.Evaluate(f.Setup,[f.Other],new HashSet<string>{"OtherBard","Hero"},f.Context,[f.Rule],now);Check(view.Suggestions.Count==potency.Expected);});
        test("Bard partial utility prevents replacing a partly useful song",()=>{var f=Fixture();f.Setup.Songs[0].Effects.Add(Effect("a","ResistMagic",20));Check(BardCoverage.Evaluate(f.Setup,[f.Other],new HashSet<string>{"OtherBard"},f.Context,[f.Rule],now).Suggestions.Count==0);});
        test("Bard same identity haste pulses do not invent contributions",()=>{var f=Fixture();f.Other.Song=f.Setup.Songs[0].Identity;f.Other.Effects[0].Identity=f.Other.Song;f.Rule.SpellIds=["a"];f.Setup.Songs[0].Effects[0].Channel=EffectChannel.OrdinaryHaste;f.Other.Effects[0].Channel=EffectChannel.OrdinaryHaste;var pulse=EquipmentPositions.Copy(f.Other);pulse.Id="second-pulse";pulse.At=now;var view=BardCoverage.Evaluate(f.Setup,[f.Other,pulse],new HashSet<string>{"OtherBard"},f.Context,[f.Rule],now);Check(view.Coverage.Count==1&&view.Suggestions.Count==1);});
        test("Bard swap preserves the complete chosen set",()=>{var f=Fixture();f.Setup.ConfirmedAuraRank=2;f.Setup.Songs.Add(new(){Identity=new("d","Retained mana",0),Gem=7,Available=true,RequiredLevel=1,Mana=0,CooldownMs=0,NonTargetedArea=true,Keep=true,Effects=[Effect("d","ManaRegen",10)]});var manaRule=new EffectRule{Id="mana",Source="Fixture",Version="1",Quality=EvidenceQuality.UserConfirmed,Kind=EffectRuleKind.Strongest,Family="ManaRegen",SpellIds=["c","d"]};Check(BardCoverage.Evaluate(f.Setup,[f.Other],new HashSet<string>{"OtherBard"},f.Context,[f.Rule,manaRule],now).Suggestions.Count==0);});
        test("Bard unknown instrument and AA context remain conditional",()=>{var f=Fixture();f.Other.Instrument=null;var view=BardCoverage.Evaluate(f.Setup,[f.Other],new HashSet<string>{"OtherBard"},f.Context,[f.Rule],now);Check(view.Suggestions.Count==0&&view.Conditions.Any(c=>c.Contains("uncertainty")));f=Fixture();f.Setup.AaContext="";Check(BardCoverage.Evaluate(f.Setup,[f.Other],new HashSet<string>{"OtherBard"},f.Context,[f.Rule],now).Suggestions.Count==0);});
        test("Bard stale nonmembers and wrong recipients cannot supply coverage",()=>{foreach(string mode in new[]{"stale","nonmember","recipient","failed"}){var f=Fixture();if(mode=="stale")f.Other.Until=now;if(mode=="recipient")f.Other.Recipient="Pet";if(mode=="failed")f.Other.SuccessfulApplication=false;Check(BardCoverage.Evaluate(f.Setup,[f.Other],mode=="nonmember"?new HashSet<string>():new HashSet<string>{"OtherBard"},f.Context,[f.Rule],now).Suggestions.Count==0);}});
        test("Bard availability actual level and Keep choices are required",()=>{foreach(string mode in new[]{"level","available","keep"}){var f=Fixture();if(mode=="level")f.Setup.Available[0].RequiredLevel=51;if(mode=="available")f.Setup.Available[0].Available=false;if(mode=="keep")f.Setup.Songs[0].Keep=true;Check(BardCoverage.Evaluate(f.Setup,[f.Other],new HashSet<string>{"OtherBard"},f.Context,[f.Rule],now).Suggestions.Count==0);}});
        test("Bard repeated damage is preserved even with a stat overlap rule",()=>{var f=Fixture();f.Setup.Songs[0].Effects[0].Channel=EffectChannel.Damage;f.Other.Effects[0].Channel=EffectChannel.Damage;Check(BardCoverage.Evaluate(f.Setup,[f.Other],new HashSet<string>{"OtherBard"},f.Context,[f.Rule],now).Suggestions.Count==0);});
        test("Bard saved swap is a plan and preserves the original gems",()=>{var f=Fixture();var suggestion=BardCoverage.Evaluate(f.Setup,[f.Other],new HashSet<string>{"OtherBard"},f.Context,[f.Rule],now).Suggestions.Single();var original=f.Setup.Songs[0].Identity;BardCoverage.SavePlan(f.Setup,suggestion,now);Check(f.Setup.Songs[0].Identity==original&&f.Setup.Planned.Single().Gem==8);});
        test("Bard reviewed durations cannot revive a known fade",()=>{var f=Fixture();f.Other.InvalidatedAt=now.AddSeconds(-.5);var rule=new SongCoverageRule{Song=f.Other.Song,Caster=f.Other.Caster,Recipient=f.Other.Recipient,Zone="Here",DurationSeconds=30,Source="Fixture"};rule.Apply(f.Other,"Here");Check(!f.Other.Fresh(now,"Hero"));});
        test("Generic group cast failures never create successful coverage",()=>{var parser=new LogParser("Hero");var state=new ConnectedSpellState();var index=new ConnectedSpellIndex([]);var cast=parser.Parse("[Fri Oct 23 12:00:00 2026] OtherBard begins casting Verses of Victory +3.")!;ConnectedSpellEvidence.Attempt(state,cast,"cast","Hero",[],index);var failure=parser.Parse("[Fri Oct 23 12:00:01 2026] OtherBard's spell is interrupted.")!;ConnectedSpellEvidence.Attempt(state,failure,"fail","Hero",[],index);Check(state.History.Any(e=>e.Caster=="OtherBard"&&e.Transition=="Interrupted / failed"));ConnectedSpellEvidence.Effect(state,new(){At=failure.Time.AddSeconds(1),Actor="Hero",Spells=["Verses of Victory"],State="Landing",LogId="landing"},index);Check(state.History.First(e=>e.Id=="landing:spell-effect").Caster=="");});
        test("Compatibility unknown below-cap conversion withholds an upgrade",()=>{var a=Effect("a","Haste",10);a.Channel=EffectChannel.WornHaste;a.Equipment=true;var b=Effect("b","Haste",20);b.Channel=EffectChannel.WornHaste;b.Equipment=true;var result=BuildCompatibility.Compare(new(){SummonedPet=true,PetLevel=50,ObservedOrdinaryAttackSpeed=140,SpeedEvidence=EvidenceQuality.Observed},[a],[b],[]);Check(result.After.OrdinaryAttackSpeed==null&&!result.CanClaimUpgrade);});
    }
}
